'use strict';
/*
 * Journal finder for "Jurnal & Paper".
 * Finds journals that already publish work like the user's paper: search OpenAlex for similar
 * recent journal articles, count which journals they appeared in, then look up each journal's
 * real metrics (h-index, 2-year mean citedness, open access, APC, DOAJ and the national/
 * international lists OpenAlex records). Nothing here is generated by AI.
 *
 * OpenAlex does not say whether a journal is in Scopus or Web of Science, or its quartile,
 * so each result links to Scimago, where the user can check the SJR quartile.
 */
const WORKS = 'https://api.openalex.org/works';
const SOURCES = 'https://api.openalex.org/sources';

/* Lists OpenAlex records for journals, shown as badges, strongest first. */
const LISTS = [
  ['ft50', 'FT50'], ['utd24', 'UTD24'], ['abdc-a-star', 'ABDC A*'], ['abdc-a', 'ABDC A'], ['abdc-b', 'ABDC B'], ['abdc-c', 'ABDC C'],
  ['cwts-core', 'CWTS Core'], ['medline', 'MEDLINE'], ['erih-plus', 'ERIH PLUS'], ['doaj', 'DOAJ'], ['scielo', 'SciELO'],
  ['sinta-s1', 'SINTA 1'], ['sinta-s2', 'SINTA 2'], ['sinta-s3', 'SINTA 3'], ['sinta-s4', 'SINTA 4'], ['sinta-s5', 'SINTA 5'], ['sinta-s6', 'SINTA 6'],
  ['kci-excellent', 'KCI Excellent'], ['kci-registered', 'KCI'], ['tci-1', 'TCI 1'], ['tci-2', 'TCI 2']
];

function finderError(message, status) { return Object.assign(new Error(message), { status }); }
const strip = s => String(s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
const shortId = id => String(id || '').replace(/^https?:\/\/openalex\.org\//i, '');

function headers() {
  const h = { Accept: 'application/json', 'User-Agent': 'ThesTalk/0.9 (academic writing assistant)' };
  if (process.env.OPENALEX_API_KEY) h.Authorization = 'Bearer ' + process.env.OPENALEX_API_KEY;
  return h;
}

async function getJSON(url, ms = 12000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  let r;
  try { r = await fetch(url, { headers: headers(), signal: controller.signal }); }
  catch (e) { throw finderError(e && e.name === 'AbortError' ? 'Journal search timed out.' : 'Journal search is unreachable right now.', e && e.name === 'AbortError' ? 504 : 502); }
  finally { clearTimeout(timer); }
  if (r.status === 429) throw finderError(process.env.OPENALEX_API_KEY ? 'The OpenAlex daily allowance is used up. Try again after 8 a.m. Malaysia time.' : 'Journal search needs a free OpenAlex API key (OPENALEX_API_KEY).', 429);
  if (r.status === 401 || r.status === 403) throw finderError('OpenAlex rejected the API key. Check OPENALEX_API_KEY in Vercel.', 502);
  if (!r.ok) throw Object.assign(finderError('Journal search failed (' + r.status + ').', 502), { httpStatus: r.status });
  try { return await r.json(); } catch (_) { throw finderError('Journal search returned an unreadable answer.', 502); }
}

function worksUrl(query, since, strict) {
  const p = new URLSearchParams();
  p.set('search', String(query).slice(0, 200));
  const filters = ['type:article', 'from_publication_date:' + since + '-01-01'];
  if (strict) filters.push('primary_location.source.type:journal');
  p.set('filter', filters.join(','));
  p.set('select', 'id,display_name,publication_year,primary_location,cited_by_count');
  p.set('per_page', '100');
  if (process.env.OPENALEX_EMAIL) p.set('mailto', process.env.OPENALEX_EMAIL);
  return WORKS + '?' + p.toString();
}

async function searchSimilar(query, since) {
  let data;
  try { data = await getJSON(worksUrl(query, since, true)); }
  catch (e) { if (e.httpStatus === 400) data = await getJSON(worksUrl(query, since, false)); else throw e; }
  return Array.isArray(data && data.results) ? data.results : [];
}

/* Count how many of the similar articles each journal published. */
function tally(works) {
  const seen = new Set();
  const bySource = new Map();
  for (const w of works) {
    const id = w && w.id;
    if (!id || seen.has(id)) continue;
    seen.add(id);
    const src = w.primary_location && w.primary_location.source;
    if (!src || !src.id || (src.type && src.type !== 'journal')) continue;
    const key = shortId(src.id);
    const entry = bySource.get(key) || { id: key, name: strip(src.display_name), matches: 0, cites: 0, samples: [] };
    entry.matches++;
    entry.cites += Number(w.cited_by_count) || 0;
    if (entry.samples.length < 2 && w.display_name) entry.samples.push({ title: strip(w.display_name).slice(0, 220), year: w.publication_year || null });
    bySource.set(key, entry);
  }
  return { searched: seen.size, sources: [...bySource.values()] };
}

function toJournal(src, hit) {
  const stats = src.summary_stats || {};
  const listed = Array.isArray(src.listed_in) ? src.listed_in : [];
  const badges = LISTS.filter(([k]) => listed.includes(k) || (k === 'doaj' && src.is_in_doaj)).map(([, label]) => label);
  const impact = Number(stats['2yr_mean_citedness']);
  const name = strip(src.display_name) || hit.name;
  return {
    id: hit.id,
    name,
    publisher: strip(src.host_organization_name),
    issn: src.issn_l || (Array.isArray(src.issn) && src.issn[0]) || '',
    homepage: typeof src.homepage_url === 'string' ? src.homepage_url : '',
    matches: hit.matches,
    samples: hit.samples,
    h: Number.isFinite(Number(stats.h_index)) ? Number(stats.h_index) : null,
    impact: Number.isFinite(impact) ? Math.round(impact * 100) / 100 : null,
    oa: !!src.is_oa,
    doaj: !!src.is_in_doaj,
    apc: Number.isFinite(Number(src.apc_usd)) && Number(src.apc_usd) > 0 ? Number(src.apc_usd) : null,
    core: !!src.is_core,
    size: Number(src.works_count) || 0,
    badges,
    topics: (Array.isArray(src.topics) ? src.topics : []).slice(0, 4).map(t => strip(t && t.display_name)).filter(Boolean),
    scimago: 'https://www.scimagojr.com/journalsearch.php?q=' + encodeURIComponent(src.issn_l || name),
    openalex: 'https://openalex.org/' + hit.id
  };
}

/* More similar papers first, then journal impact; CWTS core journals get a small lift.
   Very large multidisciplinary journals turn up in almost every search, so their count is damped a little. */
function score(j) {
  const mega = j.size > 20000 ? 1 / (1 + Math.log10(j.size / 20000)) : 1;
  return j.matches * mega * (1 + Math.log10(1 + (j.impact || 0))) + (j.core ? 1 : 0) + Math.log10(1 + (j.h || 0)) / 4;
}

async function findJournals(queries, { since = new Date().getFullYear() - 5, limit = 12 } = {}) {
  const list = (Array.isArray(queries) ? queries : []).map(q => String(q || '').trim()).filter(Boolean).slice(0, 4);
  if (!list.length) return { journals: [], searched: 0 };
  const settled = await Promise.allSettled(list.map(q => searchSimilar(q, since)));
  const works = settled.filter(s => s.status === 'fulfilled').flatMap(s => s.value);
  if (!works.length) {
    const failure = settled.find(s => s.status === 'rejected');
    if (failure) throw failure.reason;
    return { journals: [], searched: 0 };
  }
  const { searched, sources } = tally(works);
  const top = sources.sort((a, b) => b.matches - a.matches || b.cites - a.cites).slice(0, 20);
  if (!top.length) return { journals: [], searched };
  const p = new URLSearchParams();
  p.set('filter', 'openalex:' + top.map(s => s.id).join('|'));
  p.set('select', 'id,display_name,issn_l,issn,host_organization_name,summary_stats,works_count,is_oa,is_in_doaj,apc_usd,homepage_url,is_core,listed_in,topics,type,is_preprint_repository');
  p.set('per_page', '50');
  if (process.env.OPENALEX_EMAIL) p.set('mailto', process.env.OPENALEX_EMAIL);
  const data = await getJSON(SOURCES + '?' + p.toString());
  const byId = new Map((data && Array.isArray(data.results) ? data.results : []).map(s => [shortId(s.id), s]));
  const journals = top
    .map(hit => ({ hit, src: byId.get(hit.id) }))
    .filter(({ src }) => src && src.type === 'journal' && !src.is_preprint_repository)
    .map(({ hit, src }) => toJournal(src, hit))
    .sort((a, b) => score(b) - score(a))
    .slice(0, limit);
  return { journals, searched };
}

module.exports = { findJournals, tally, toJournal, score, LISTS };
